using System.Security.Cryptography;using System.Text;namespace QuantForge.Core;public sealed record AndroidStrategySelection(string SelectionFingerprint,string StrategyArtifactFingerprint,string StrategyId,string StrategyFingerprint);public static class AndroidStrategySelectionRules{public static AndroidStrategySelection Create(StrategyAdmissionArtifact artifact){StrategyAdmissionArtifactRules.Validate(artifact);var m=artifact.Envelope.Manifest;var text=string.Join("|",artifact.ArtifactFingerprint,m.StrategyId,m.SourceFingerprint);var fp=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));return new(fp,artifact.ArtifactFingerprint,m.StrategyId,m.SourceFingerprint);}public static void Validate(AndroidStrategySelection value,StrategyAdmissionArtifact artifact){if(Create(artifact)!=value)throw new InvalidOperationException("Android strategy selection does not match admitted strategy evidence.");}}
